# ---- Direct links: no flash of Home --------------------------------------
# A link with ?gene=, ?variant= or ?region= shows "Opening <term>" in place of the
# page until the server has switched to the requested view (or shown its
# not-in-release message), instead of showing Home first. Gives up after 25 s.
deeplink_js <- tags$script(HTML(paste0(
  "(function(){try{var p=new URLSearchParams(location.search);var t=p.get('gene')||p.get('variant')||p.get('region');",
  "var tab=p.get('tab');if(!t||(tab&&tab==='Home'))return;var de=document.documentElement;de.classList.add('adx-dl');",
  "var st=document.createElement('style');st.textContent='html.adx-dl .tab-content,html.adx-dl #view_strip,html.adx-dl .site-footer{visibility:hidden}",
  ".adx-dl-box{position:fixed;left:0;right:0;top:40%;display:flex;flex-direction:column;align-items:center;gap:12px;z-index:900;font-size:15px;color:#19354a}",
  ".adx-dl-sp{width:28px;height:28px;border:3px solid #dce3e8;border-top-color:#3d6289;border-radius:50%;animation:adxsp 0.9s linear infinite}",
  "@keyframes adxsp{to{transform:rotate(360deg)}}@media (prefers-reduced-motion:reduce){.adx-dl-sp{animation:none}}';",
  "document.head.appendChild(st);var box=null;function show(){if(box||!document.body)return;box=document.createElement('div');box.className='adx-dl-box';",
  "box.setAttribute('role','status');box.setAttribute('aria-live','polite');var sp=document.createElement('div');sp.className='adx-dl-sp';",
  "var tx=document.createElement('div');tx.textContent='Opening '+t+'\\u2026';box.appendChild(sp);box.appendChild(tx);document.body.appendChild(box);}",
  "function done(){de.classList.remove('adx-dl');if(box&&box.parentNode)box.parentNode.removeChild(box);clearInterval(iv);}",
  "var t0=Date.now();var iv=setInterval(function(){show();var a=document.querySelector('.navbar .nav-link.active');",
  "var on=a?a.textContent.trim():'';if((on&&on!=='Home')||document.querySelector('.shiny-notification')||Date.now()-t0>25000)setTimeout(done,250);},150);",
  "if(window.jQuery)jQuery(document).on('shiny:disconnected',done);}catch(e){}})();")))

# Styles live in app/www/explorer.css; the ?v= hash makes browsers fetch a changed file
app_css <- tags$head(deeplink_js)
explorer_css <- tags$link(rel = "stylesheet",
  href = paste0("explorer.css?v=", substr(unname(tools::md5sum(file.path("www", "explorer.css"))), 1, 8)))

## Keep compiled styles inside the app folder so a fresh server reuses them.
options(sass.cache = sass::sass_file_cache(file.path(getwd(), "sass-cache")))

app_theme <- bs_theme(
  version = 5, primary = "#19354A", "navbar-bg" = "#ffffff",
  bg = "#ffffff", fg = "#233947",
  "body-bg" = "#ffffff", "card-bg" = "#ffffff",
  "border-color" = "#dde2e6",
  base_font = font_google("Figtree", local = FALSE),
  heading_font = font_google("Figtree", local = FALSE),
  code_font = font_google("IBM Plex Mono", local = FALSE)
)

# collapse the mobile navbar after a tab is chosen
nav_js <- tags$script(HTML("(function(){document.addEventListener('click',function(e){var a=e.target.closest('.navbar .nav-link');if(!a||a.classList.contains('dropdown-toggle'))return;setTimeout(function(){var c=document.querySelector('.navbar-collapse.show');if(!c)return;if(window.bootstrap&&bootstrap.Collapse){bootstrap.Collapse.getOrCreateInstance(c).hide();return;}c.classList.remove('show');var t=document.querySelector('.navbar-toggle,.navbar-toggler');if(t)t.setAttribute('aria-expanded','false');},10);});})();"))

# name every control and figure for screen readers
a11y_js <- tags$script(HTML("(function(){function AON(ev,fn){if(window.jQuery){window.jQuery(document).on(ev,fn);}else{document.addEventListener(ev,fn);}}var NM={locus_prev:'Previous locus',locus_next:'Next locus',hero_search:'Search for a gene, rsID, Ensembl ID or region'};var FIG={p_landscape:'Genome-wide AD locus landscape',p_ctxtier:'Evidence by cell type and tier',cty_tier_plot:'Tier distribution for the selected cell type',bt_tier_plot:'Tier distribution for the matched list',ql_pip:'Highest AD-side probability per variant-gene row, by method',ql_cv2f:'cV2F score distribution',ql_sig:'GWAS significance classes',trans_circos:'Trans target genes drawn around a chromosome circle',region_fig:'Regional evidence around the selected locus',p_region:'Regional evidence around the selected locus',home_river:'Context to modality to evidence tier flow'};function clean(n){if(!n)return '';var k=n.cloneNode(true);var b=k.querySelector('.ibub');if(b&&b.parentNode)b.parentNode.removeChild(b);return k.textContent.trim();}function figName(im){var p=im.parentElement,h=null,id=null;for(var i=0;i<8&&p;i++){if(!id&&p.id&&FIG[p.id])id=p.id;if(!h){var f=p.querySelector('.dc-figt');if(f)h=f;}p=p.parentElement;}if(id)return FIG[id];var t=clean(h);return t?t:'';}function fix(){document.querySelectorAll('.shiny-input-container').forEach(function(c){var t=clean(c.querySelector('label'));if(!t)return;c.querySelectorAll('input,select,textarea').forEach(function(el){if(el.type==='checkbox'||el.type==='radio')return;if(el.closest&&el.closest('label'))return;if(!el.getAttribute('aria-label')&&!el.getAttribute('aria-labelledby'))el.setAttribute('aria-label',t);});});Object.keys(NM).forEach(function(id){var e=document.getElementById(id);if(e&&!e.getAttribute('aria-label'))e.setAttribute('aria-label',NM[id]);var s=document.getElementById(id+'-selectized');if(s&&!s.getAttribute('aria-label'))s.setAttribute('aria-label',NM[id]);});document.querySelectorAll('button').forEach(function(b){if(b.getAttribute('aria-label')||b.textContent.trim())return;var t=b.getAttribute('title')||NM[b.id]||b.id||'Button';b.setAttribute('aria-label',t.split('_').join(' '));});var tg=document.querySelector('.navbar-toggler,.navbar-toggle');if(tg&&!tg.getAttribute('aria-label'))tg.setAttribute('aria-label','Main menu');document.querySelectorAll('img').forEach(function(im){var a=im.getAttribute('alt');if(a&&a!=='Plot object'&&a.indexOf('Figure')!==0)return;var t=figName(im);im.setAttribute('alt',t?('Figure. '+t+'. The same values are listed in the table or export below this figure.'):'Figure. Chart of release data; the same values are available in the table or export below.');});document.querySelectorAll('svg').forEach(function(s){if(s.getAttribute('role')||s.getAttribute('aria-hidden'))return;if(s.querySelector('[tabindex]'))return;if(s.getAttribute('aria-label')||s.querySelector('title'))s.setAttribute('role','img');else s.setAttribute('aria-hidden','true');});document.querySelectorAll('.plotly').forEach(function(p){var kb=!!p.querySelector('[tabindex]');p.setAttribute('role',kb?'group':'img');if(p.getAttribute('aria-label'))return;var id=p.id||(p.parentElement&&p.parentElement.id);p.setAttribute('aria-label',(FIG[id]||'Interactive chart')+'. A CSV export of the same values is provided beside this figure.');});var ig=document.querySelector('#igv_div select');if(ig&&!ig.getAttribute('aria-label')){ig.setAttribute('aria-label','Chromosome shown in the genome browser');ig.setAttribute('size','1');}document.querySelectorAll('.vs-wrap,#cty_stats,#bt_summary,.rv-stat').forEach(function(e){if(!e.getAttribute('aria-live'))e.setAttribute('aria-live','polite');});}document.addEventListener('DOMContentLoaded',fix);AON('shiny:value',function(){setTimeout(fix,60);});AON('shiny:idle',function(){setTimeout(fix,60);});setTimeout(fix,800);setTimeout(fix,2200);setTimeout(fix,5000);var _t=null;var _mo=new MutationObserver(function(){if(_t)clearTimeout(_t);_t=setTimeout(fix,250);});if(document.body)_mo.observe(document.body,{childList:true,subtree:true});})();"))

# loader sweep and disconnect banner
conn_js <- tags$script(HTML("(function(){function AON(ev,fn){if(window.jQuery){window.jQuery(document).on(ev,fn);}else{document.addEventListener(ev,fn);}}function sweep(){document.querySelectorAll('.shiny-spinner-output-container').forEach(function(c){var out=c.querySelector('.shiny-bound-output');if(!out)return;var has=out.children.length>0||out.textContent.trim().length>0;var ld=c.querySelector('.load-container');if(has&&ld)ld.style.display='none';if(!has&&ld)ld.style.display='';});}AON('shiny:value',function(){setTimeout(sweep,80);});AON('shiny:idle',function(){setTimeout(sweep,80);});AON('shiny:error',function(){setTimeout(sweep,80);});setInterval(sweep,2000);function banner(){var b=document.getElementById('conn-lost');if(b)return b;b=document.createElement('div');b.id='conn-lost';b.setAttribute('role','alert');b.setAttribute('aria-live','assertive');b.innerHTML='<span>Connection lost. Displayed results may be stale.</span>';var r=document.createElement('button');r.type='button';r.className='conn-btn';r.textContent='Reload this view';r.addEventListener('click',function(){location.reload();});b.appendChild(r);document.body.appendChild(b);return b;}function lost(){banner();document.body.classList.add('conn-stale');document.querySelectorAll('.tour-wrap').forEach(function(t){if(t.parentNode)t.parentNode.removeChild(t);});['main-content'].forEach(function(id){var m=document.getElementById(id);if(m)m.removeAttribute('aria-hidden');});var nv=document.querySelector('nav.navbar');if(nv)nv.removeAttribute('aria-hidden');}AON('shiny:disconnected',lost);AON('shiny:sessionended',lost);})();"))

